// One block computes one output element C[m] = dot(A[m, :], B[:])
// Vectorized loads via float4 using CuTe's recast, cooperative reduction across the block.
template <typename T, int Threads>
__global__ void matvec_kernel(
    const T* __restrict__ Aptr,
    const T* __restrict__ Bptr,
    T* __restrict__ Cptr,
    int M, int K)
{
  int m = blockIdx.x;
  if (m >= M) return;

  // Full tensors via CuTe
  Tensor mA = make_tensor(make_gmem_ptr(Aptr), make_shape(M, K), make_stride(K, 1));
  Tensor mB = make_tensor(make_gmem_ptr(Bptr), make_shape(K), make_stride(1));

  // Row slice for this block: shape (K)
  Tensor gA = mA(m, _);

  int tid = threadIdx.x;

  float acc = 0.0f;

  // Vectorized portion: try to recast to float4 view when possible
  constexpr int VecWidth = 4;
  int K4 = K / VecWidth;
  int Krem = K - K4 * VecWidth;

  if (K4 > 0) {
    // Use explicit pointer-based float4 reinterpretation to avoid CuTe
    // recast/compose issues with dynamically-sized layouts.
    const float4* Aptr4 = reinterpret_cast<const float4*>(Aptr + (size_t)m * K);
    const float4* Bptr4 = reinterpret_cast<const float4*>(Bptr);
    for (int i = tid; i < K4; i += Threads) {
      float4 a4 = Aptr4[i];
      float4 b4 = Bptr4[i];
      acc += a4.x * b4.x + a4.y * b4.y + a4.z * b4.z + a4.w * b4.w;
    }
  }

  // Remainder (scalar) portion
  int rem_start = K4 * VecWidth;
  for (int i = rem_start + tid; i < K; i += Threads) {
    float av = gA(i);
    float bv = mB(i);
    acc += av * bv;
  }

  // Block-level reduction: warp shuffle then shared memory across warps
  unsigned mask = 0xffffffffu;
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    acc += __shfl_down_sync(mask, acc, offset);
  }

  __shared__ float warp_sums[Threads / 32];
  int lane = tid % 32;
  int warp_id = tid / 32;
  if (lane == 0) {
    warp_sums[warp_id] = acc;
  }
  __syncthreads();

  if (warp_id == 0) {
    float val = (lane < (Threads / 32)) ? warp_sums[lane] : 0.0f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      val += __shfl_down_sync(mask, val, offset);
    }
    if (lane == 0) {
      Cptr[m] = static_cast<T>(val);
    }
  }
